/* ============ P: PROFILES, PRIVATE LAYER & ACCESS, SAFETY ============ */
function profileView(id,r,o={}){
 const me=id==='me'||id==='couple',self=me&&!o.asOther;const owner=id==='couple'?'couple':'me';if(me&&r.p.preview)S.ui[id==='couple'?'couplePreview':'profilePreview']=r.p.preview;const p=person(id);const ix=(S.ui.ph||{})[id]||0;const t=r.p.t||'about';
 const displayName=me?(p.name||p.nick||L('Ты','You')):pname(id);const posts=(me?S.myPosts.filter(x=>x.status==='published'&&!x.hiddenByPair&&x.author===id):allPosts().filter(x=>x.author===id)).sort((a,b)=>b.t-a.t);
 const mutual=!me&&isMatch(id),liked=!me&&social().likesOut.some(l=>l.p===id),canLike=!self&&(p.dating||p.socialLikes);
 const sh=me?null:shared(id);const inert=h=>o.asOther?h.replace(/ data-(act|go|p|v|id)=("[^"]*"|'[^']*')/g,'').replace(/<button /g,'<button disabled tabindex="-1" '):h;
 const keys=[...fmtList(p.format).slice(0,2).map(x=>opt('format',x)),...fmtList(p.role).filter(v=>v!=='none').slice(0,2).map(v=>opt('role',v)),...(p.dating?(p.seek||[]).slice(0,2).map(s=>opt('seek',s)):[])].filter(Boolean);
 const likeBtn=p.pair?(p.dating?`<button class="btn primary" data-act="meetPair" data-v="${id}">${I.heart}${L('Познакомиться','Meet')}</button>`:''):mutual?`<button class="btn primary" data-act="openChat" data-v="${id}">${I.chat}${L('Написать','Message')}</button>`:liked?`<button class="btn on" data-act="unlikeP" data-v="${id}" aria-pressed="true">${I.heartf}${L('Симпатия','Liked')}</button>`:canLike?`<button class="btn primary" data-act="likeProfile" data-v="${id}">${I.heartf}${L('Нравится','Like')}</button>`:`<button class="btn soft off" title="${L('Не принимает симпатии','Not accepting likes')}">${I.heart}${L('Симпатии выкл.','Likes off')}</button>`;
 const pending=social().reqOut.find(x=>x.p===id&&x.status==='pending');
 const acts=self?`<div class="row g8" style="margin-top:16px"><button class="btn primary" data-go="P02" data-p='${esc(JSON.stringify({owner}))}'>${I.edit}${L('Редактировать','Edit profile')}</button><button class="btn soft" data-act="shareProfile">${I.share}${L('Поделиться','Share')}</button></div>`
  :inert(`<div class="p-acts">${!o.asOther?authorPicker():''}${likeBtn}<button class="btn soft" data-act="follow" data-v="${id}" aria-pressed="${social('me').follows.has(id)}">${social('me').follows.has(id)?`${I.check}${L('Подписка','Following')}`:L('Подписаться','Follow')}</button><button class="ibtn" data-act="reqAccess" data-v="${id}" aria-label="${pending?L('Запрос на расширенный профиль отправлен','Private profile request sent'):L('Запросить расширенный профиль','Request private profile')}" title="${L('Расширенный профиль','Private profile')}">${pending?I.clock:I.key}</button></div>`);
 const orgEvents=allEventIds().filter(e=>EV(e).organizer===id&&!isPast(e)&&!EV(e).cancelled&&EV(e).status!=='review');
 const modOf=Object.keys(COMMUNITIES).filter(c=>COMMUNITIES[c].mods.includes(id));
 const kv=identityFields().map(([k,title])=>[title,IDENTITY_MULTI.includes(k)?fmtList(p[k]).map(v=>opt(k,v)).join(', '):opt(k,p[k])]).filter(x=>x[1]);
 /* V8: one page — profile, then the private profile right after it when access is open. No tabs. */
 const body=`${T(p.bio)?grp(L('О себе','About'),md(T(p.bio),'bio')):self?grp(L('О себе','About'),`<button class="li" data-go="P02" data-p='${esc(JSON.stringify({owner}))}'><span class="ico">${I.edit}</span><span class="tx"><b>${L('Добавь пару слов о себе','Add a few words about yourself')}</b><small>${L('Так людям проще начать разговор','It makes starting a conversation easier')}</small></span>${I.chev}</button>`,{list:1}):''}
  ${kv.length?grp(L('Кратко','At a glance'),`<dl class="kv">${kv.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`):''}
  ${grp(L('Интересы','Interests'),pubJars(id).length?jarShelf(pubJars(id),{pre:1,act:self?(id==='couple'?'editCoupleJar':'editJar'):'topic',who:id,moreAct:self?(id==='couple'?'coupleJars':'myJarsAll'):'allJars'}):`<p class="note">${self?(id==='couple'?L('Добавьте ваши общие интересы.','Add your shared interests.'):L('Открой интересы в «Я» — они появятся здесь.','Make interests public in Me — they’ll show here.')):L(`${esc(pname(id))} пока не открыл(а) интересы.`,`${esc(pname(id))} hasn’t shared interests yet.`)}</p>`+(self&&id==='couple'?`<button class="btn soft sm mt12" data-act="coupleJarAdd">${I.plus}${L('Добавить общие интересы','Add couple interests')}</button>`:''),{foot:pubJars(id).length&&!self?L('Нажми на баночку — увидишь, что это и как у тебя.','Tap a jar to see what it is and how it is for you.'):''})}
  ${self?myPrivSection(owner):me?privSection(id,o):`<div data-private-context="${id}">${privSection(id)}</div>`}
  ${posts.length?`<div class="grp"><div class="grp-t"><span>${L('Публикации','Posts')} · ${posts.length}</span></div><div class="posts">${inert(posts.slice(0,3).map((x,i)=>postCard(x,{i})).join(''))}</div></div>`:''}
  ${modOf.length?`<div class="grp"><div class="grp-t"><span>${L('Ведёт сообщества','Runs communities')}</span></div>${modOf.map((c,i)=>commCard(c,{i})).join('')}</div>`:''}
  ${orgEvents.length?`<div class="grp"><div class="grp-t"><span>${L('Организует','Organising')}</span></div>${orgEvents.map(e=>eventCard(e,{row:1,neutral:o.asOther})).join('<div style="height:8px"></div>')}</div>`:''}`;
 const html=`<header class="bar overlay"><button class="ibtn glass" data-back aria-label="${L('Назад','Back')}">${I.back}</button><span style="flex:1"></span>${self?`<button class="ibtn glass" data-go="P02" data-p='${esc(JSON.stringify({owner}))}' aria-label="${L('Редактировать','Edit')}">${I.edit}</button>`:o.asOther?`<button class="ibtn glass" data-act="p3Menu" aria-label="${L('Ещё','More')}">${I.more}</button>`:inert(`<button class="ibtn glass" data-act="profileMenu" data-v="${id}" aria-label="${L('Ещё','More')}">${I.more}</button>`)}</header>
 <div class="view nodock top0"><div class="wrap">
 ${o.banner||''}
 <div class="hero">${me&&!p.photo?`<div class="plate" style="${PL.rose};position:absolute;inset:0"><span class="pi">${id==='couple'?I.couple:I.me}</span></div>`:photoBg(id,ix)+bigPhoto(id,ix)}${photoBars(id,ix)}${photoCount(id)>1?`<button class="pc-zone l" data-act="pPhoto" data-v="-1" aria-label="${L('Предыдущее фото','Previous photo')}"></button><button class="pc-zone r" data-act="pPhoto" data-v="1" aria-label="${L('Следующее фото','Next photo')}"></button>`:''}${p.photo?`<button class="pc-zone c" data-act="pView" aria-label="${L('Открыть фото на весь экран','Open photo full screen')}"></button>`:''}
  <div class="pc-info"><h2 class="pc-name"><span class="pcn">${esc(displayName)}</span>${p.age?`<span>${p.age}</span>`:''}${nameBadges(p)}</h2><div class="pc-who">${[whoLine(id),placeLine(id)].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}${!self&&p.online?`<span class="on">${L('в сети','online')}</span>`:''}</div>${followCounts(id)}${keys.length?`<div class="pc-keys">${keys.map(k=>`<span>${esc(k)}</span>`).join('')}</div>`:''}</div></div>
 ${o.before||''}${acts}${pairLine(id,o)}${o.after||''}
 ${!me&&mutual?`<p class="note center mt8">${L('Вы совпали — можно переписываться','You matched — you can chat')}</p>`:''}
 ${!me?`<button class="why mt12" data-go="P05" data-id="${id}">${venn(sh.few?'?':sh.match.length,{mini:1})}<span class="grow"><b>${esc(sharedSummary(id))}</b><span>${L('Что у вас общего','What you share')}</span></span>${I.chev}</button>`:o.asOther?`<div class="why mt12" aria-disabled="true">${venn('?',{mini:1})}<span class="grow"><b>${L('Общие темы — у каждого свои','Shared topics differ per person')}</b><span>${L('Человек увидит своё совпадение с тобой','Each person sees their own overlap with you')}</span></span></div>`:''}
 ${body}</div></div>`;if(me)delete S.ui[id==='couple'?'couplePreview':'profilePreview'];return html;
}
SC.P01={title:p=>pname(p.id),valid:p=>!!PEOPLE[p.id]&&!isBlocked(p.id),render:(p,r)=>profileView(p.id,r),after:()=>fillJars()};
SC.P03={title:()=>L('Как видят мой профиль','My profile as others see it'),render:(p,r)=>{const lv=p.lv==='granted'?'granted':'all';S.ui.viewGrant=lv==='granted';try{
 const top=`<div class="pv-panel"><div class="alert info">${I.eye}<span><b>${L('Так тебя видят другие','This is how others see you')}</b>${lv==='granted'?L('Так видит человек, которому ты открыл(а) расширенный профиль. Кнопки здесь не работают — это просмотр.','As seen by someone you shared your private profile with. Buttons don’t work here — it’s a preview.'):L('Так видит любой участник без доступа. Кнопки здесь не работают — это просмотр.','As any member without access sees it. Buttons don’t work here — it’s a preview.')}</span></div>${seg([['all',L('Любой участник','Any member')],['granted',L('С доступом','With access')]],lv,'p3lv')}</div>`;
 return profileView(p.owner==='couple'?'couple':'me',r,{asOther:true,grant:lv,banner:'',before:top});}finally{S.ui.viewGrant=false;}},after:()=>fillJars()};
/* «as others see me» menu: the preview's own actions (it is your profile, so editing is one tap away) */
ACT.p3Menu=()=>{const r=cur(),owner=r.p.owner==='couple'?'couple':'me',lv=r.p.lv==='granted'?'granted':'all';sheet(()=>({title:L('Мой профиль','My profile'),body:`<div class="card list">${linkRow({act:'p3Go',v:'P02',icon:'edit',title:L('Редактировать профиль','Edit profile'),noChev:1})}${linkRow({act:'p3Go',v:'P04',icon:'key',title:L('Расширенный профиль','Private profile'),sub:L('Текст, фото и видео, кто может просить','Text, photos & video, who can ask'),noChev:1})}${linkRow({act:'p3Lv',v:lv==='granted'?'all':'granted',icon:'eye',title:lv==='granted'?L('Посмотреть как любой участник','View as any member'):L('Посмотреть как человек с доступом','View as someone with access'),noChev:1})}${owner==='me'?linkRow({act:'shareProfile',icon:'link',title:L('Скопировать ссылку на профиль','Copy profile link'),noChev:1}):''}</div>`}));};
ACT.p3Go=a=>{const r=cur(),owner=r.p.owner==='couple'?'couple':'me';closeSheet(true);go(a.dataset.v,{owner});};
ACT.p3Lv=a=>{closeSheet(true);const r=cur();r.p={...r.p,lv:a.dataset.v};refresh();};
ACT.p3lv=a=>{const r=cur();r.p={...r.p,lv:a.dataset.v};refresh();};

ACT.pPhoto=a=>{const id=cur().p.owner==='couple'||cur().id==='Q03'?'couple':cur().id==='P03'?'me':cur().p.id;const preview=cur().p.preview;if(preview)S.ui[id==='couple'?'couplePreview':'profilePreview']=preview;if(!stepPhoto(id,+a.dataset.v)){if(preview)delete S.ui[id==='couple'?'couplePreview':'profilePreview'];const h=$('.hero');h?.classList.remove('nudge-l','nudge-r');void h?.offsetWidth;h?.classList.add(+a.dataset.v<0?'nudge-l':'nudge-r');return;}const h=$('.hero');const ix=S.ui.ph[id];const img=$('.hero>img:not(.mbg),.hero>.plate');if(img){const t=document.createElement('div');t.innerHTML=bigPhoto(id,ix);img.replaceWith(t.firstElementChild);}const bg=$('.hero>.mbg');if(bg){const t=document.createElement('div');t.innerHTML=photoBg(id,ix);if(t.firstElementChild)bg.replaceWith(t.firstElementChild);}$$('.hero .pc-bars i').forEach((b,i)=>b.classList.toggle('on',i===ix));if(preview)delete S.ui[id==='couple'?'couplePreview':'profilePreview'];};
ACT.pView=()=>{const id=cur().p.owner==='couple'||cur().id==='Q03'?'couple':cur().id==='P03'?'me':cur().p.id;const preview=cur().p.preview;openViewer(preview?(preview.photos||[]).map(ph=>({type:'image',src:IMG(ph)})):photoItems(id),(S.ui.ph||{})[id]||0);};
ACT.toMap=()=>openMe('X01');
ACT.shareProfile=()=>toast(L('Ссылка на профиль скопирована. Без входа она ничего не покажет','Profile link copied. It shows nothing without signing in'),{type:'ok'});
ACT.follow=a=>{const id=a.dataset.v;if(!canAct('follow','me')||isBlocked(id)||id==='me')return;const on=!social('me').follows.has(id);on?social('me').follows.add(id):social('me').follows.delete(id);
 if(a.classList.contains('btn')&&a.closest('.pc-foot')){a.textContent=on?L('Ты подписан(а)','Following'):L('Подписаться','Follow');}else refresh();
 toast(on?L(`Подписка на ${pname(id)}: посты появятся в «Подписках». Чат это не открывает`,`Following ${pname(id)}: posts appear in Following. This doesn’t open a chat`):L('Ты отписался(ась)','Unfollowed'),{type:on?'ok':''});};
/* R04 — like from a social profile without enrolling in discovery */
ACT.likeProfile=a=>{const id=a.dataset.v;
 if(!authorProfile()?.dating&&!authorProfile()?.socialLikes){toast(L('Симпатии выключены. Включи их в настройках приватности.','Likes are off. Enable them in privacy settings.'),{type:'warn',action:{label:L('Настройки','Settings'),fn:()=>go('K04')}});return;}const ticket=authorTicket('me');const doLike=()=>run(a,()=>{if(!validAuthor(ticket)||actionAuthor()!=='me')return;likePerson(id,'profile');refresh();},{ms:300});
 if(authorProfile()?.dating||S.ui.r04seen)return doLike();
 sheet(()=>({title:L('Симпатия из профиля','Like from a profile'),lead:`<span class="ico l">${I.heart}</span>`,body:`<div class="fact"><i class="g">${I.check}</i><span>${L(`Если ${esc(pname(id))} ответит взаимностью, откроется личный чат.`,`If ${esc(pname(id))} likes you back, a private chat opens.`)}</span></div><div class="fact"><i class="g">${I.check}</i><span>${L('Твой профиль не появится в подборке знакомств — они у тебя выключены.','Your profile won’t appear in Discover — your dating is off.')}</span></div><div class="fact"><i class="v">${I.info}</i><span>${L('Симпатию можно отменить, человек об этом не узнает.','You can withdraw the like; they won’t be told.')}</span></div>`,foot:`<button class="btn primary" data-act="r04ok" data-v="${id}">${I.heartf}${L('Отправить симпатию','Send like')}</button>`}));};
ACT.r04ok=a=>{S.ui.r04seen=1;closeSheet(true);run(null,()=>{likePerson(a.dataset.v,'profile');refresh();},{ms:300});};
ACT.unlikeP=a=>ACT.unlike(a);

/* profile menu: share / report / block */
ACT.profileMenu=a=>{const id=a.dataset.v;sheet(()=>({title:esc(pname(id)),body:`<div class="card list">${linkRow({act:'shareProfile',icon:'link',title:L('Скопировать ссылку','Copy link'),noChev:1})}${social().likesOut.some(l=>l.p===id)?linkRow({act:'unlike',v:id,icon:'heart',title:L('Отменить симпатию','Withdraw like'),noChev:1}):''}${PEOPLE[id]&&!PEOPLE[id].pair?linkRow({act:'giftPremium',v:id,icon:'crown',tone:'l',title:L('Подарить Premium','Gift Premium'),noChev:1}):''}${linkRow({act:'report',v:'person',icon:'flag',cls:'danger',title:L('Пожаловаться','Report'),noChev:1})}${linkRow({act:'block',v:id,icon:'block',cls:'danger',title:L('Заблокировать','Block'),sub:L('Прекратит контакт и все доступы','Ends contact and all access'),noChev:1})}</div>`}));};
/* S02 — report */
ACT.report=a=>{const kind=a.dataset.v||'person';S.ui.rp={why:'',block:kind==='person',who:a.dataset.who||null};closeSheet(true);
 sheet(()=>{const o=S.ui.rp;return{title:L('Пожаловаться','Report'),body:`<p class="lead">${L('Жалобу рассмотрит модератор. Человек не узнает, кто пожаловался.','A moderator reviews the report. The person won’t know who reported.')}</p>${[['threat',L('Угрозы или шантаж','Threats or blackmail')],['private',L('Чужие приватные материалы','Someone else’s private content')],['minor',L('Похоже на несовершеннолетнего','Looks underage')],['spam',L('Спам или мошенничество','Spam or scam')],['other',L('Другое','Something else')]].map(([k,l])=>`<button class="radio ${o.why===k?'on':''}" data-act="rpWhy" data-v="${k}"><i></i><span class="tx">${l}</span></button>`).join('')}
 <label class="field mt16"><span>${L('Подробности','Details')}<i>${L('необязательно','optional')}</i></span><textarea class="inp" id="rpText" rows="3" maxlength="500"></textarea></label>${kind==='person'||S.ui.rp.who?`<div class="card list">${toggleRow('rpBlock',L('Также заблокировать','Also block'),L('Сразу прекратить контакт','End contact right away'),o.block)}</div>`:''}`,
 foot:`<button class="btn danger" data-act="rpSend" data-v="${kind}">${L('Отправить жалобу','Send report')}</button>`};});};
ACT.rpWhy=a=>{S.ui.rp.why=a.dataset.v;resheet();};
ACT.rpBlock=()=>{S.ui.rp.block=!S.ui.rp.block;resheet();};
ACT.rpSend=a=>{if(!S.ui.rp.why){toast(L('Выбери причину жалобы','Choose a reason'),{type:'err'});$('#sheet .radio')?.classList.add('shake');return;}
 const id=S.ui.rp.who||cur().p.id;run(a,()=>{closeSheet();if(S.ui.rp.block&&id&&PEOPLE[id])doBlock(id);},{ok:L('Жалоба отправлена. Сообщим о решении в уведомлениях','Report sent. We’ll notify you of the decision')});};
ACT.block=a=>{const id=a.dataset.v;closeSheet(true);ask({icon:'block',tone:'l',title:L(`Заблокировать ${esc(pname(id))}?`,`Block ${esc(pname(id))}?`),text:L('Симпатии, чат и выданные доступы прекратятся сразу. Человек не получит уведомление. Разблокировка не вернёт доступы.','Likes, chat and any access you shared end immediately. They won’t be notified. Unblocking doesn’t restore access.'),ok:L('Заблокировать','Block'),danger:true}).then(ok=>{if(ok)run(null,()=>doBlock(id),{ok:L('Заблокировано','Blocked')});});};
function doBlock(id){social().reqOut=social().reqOut.filter(x=>x.p!==id);social().reqIn=social().reqIn.filter(x=>x.p!==id);S.notifs=S.notifs.filter(x=>x.p!==id);social().likesIn=social().likesIn.filter(x=>x.p!==id);S.blocked.unshift({p:id,t:Date.now()});social().matches=social().matches.filter(m=>m.p!==id);social().likesOut=social().likesOut.filter(l=>l.p!==id);social().sharedByMe=social().sharedByMe.filter(x=>x.p!==id);social('me').follows.delete(id);S.graph[id]?.delete('me');delete S.threads[id];if(S.pair?.social){const d=social('couple');d.follows.delete(id);for(const k of ['reqOut','reqIn','sharedByMe','likesIn','likesOut','matches'])d[k]=d[k].filter(x=>x.p!==id);delete d.threads[id];}
 const st=stack();while(st.length>1&&st[st.length-1].p&&st[st.length-1].p.id===id)st.pop();render('back');}

/* P05 — shared interests: categories, no universal score */
SC.P05={title:()=>L('Что у вас общего','Shared interests'),valid:p=>!!PEOPLE[p.id]&&!isBlocked(p.id),render:(p)=>{const id=p.id;const s=shared(id);const g=receivedGrant(id);
 return `${bar(L('Что у вас общего','Shared interests'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">
 ${venn(s.few?'?':s.match.length,{pre:1})}<p class="center note" style="margin-top:6px">${L('Ты и','You and')} ${esc(pname(id))}</p>
 <div class="card mt16">
  <div class="cat"><span class="ico g">${I.check}</span><div class="tx"><b>${L('Совпадает','In common')}</b>${s.match.length?`<div class="chips">${s.match.map(m=>`<span class="chip hit">${esc(topic(m))}</span>`).join('')}</div>`:`<p class="note">${L('Пока нет общих открытых тем','No shared public topics yet')}</p>`}</div></div>
  <div class="cat"><span class="ico v">${I.couple}</span><div class="tx"><b>${L('Дополняется','Complements')}</b>${s.complement.length?s.complement.map(c=>`<p class="note" style="color:var(--ink);margin-top:4px">${esc(c)}</p>`).join(''):`<p class="note">${L('Роли и направления пока не пересекаются','Roles and directions don’t meet yet')}</p>`}</div></div>
  <div class="cat"><span class="ico a">${I.warn}</span><div class="tx"><b>${L('Стоит обсудить','Worth discussing')}</b>${s.discuss.length?s.discuss.map(c=>`<p class="note" style="color:var(--ink);margin-top:4px">${esc(c)}</p>`).join(''):`<p class="note">${L('Явных различий не видно','No obvious differences')}</p>`}</div></div>
  ${s.few?`<div class="cat"><span class="ico">${I.info}</span><div class="tx"><b>${L('Мало данных','Not enough data')}</b><p class="note">${L('Пока мало общего контекста — это не оценка человека.','Not much shared context yet — this isn’t a judgement of the person.')}</p></div></div>`:''}
 </div>
 <div class="alert mt12">${I.lock}<span>${L('Сравниваем только то, что вы оба открыли: публичные интересы, формат и роль.','We compare only what you both made visible: public interests, format and role.')} ${g?L('Расширенный профиль доступен отдельно и не участвует в публичном объяснении.','The private profile is available separately and excluded from the public explanation.'):L('Скрытые темы и границы не участвуют и не раскрываются.','Hidden topics and limits are never used or revealed.')}</span></div>
 ${S.me.jars.filter(j=>j.vis==='public').length<3?`<button class="btn soft mt12" data-act="toMap">${L('Открыть больше своих интересов','Make more of your interests public')}</button>`:''}
 </div></div>`;},after:()=>playVenn()};

/* P06 — request private access: categories, quota, no message, no chat */
ACT.reqAccess=a=>{const id=a.dataset.v||cur().p.id;if(!needAge(()=>ACT.reqAccess({dataset:{v:id}})))return;
 const pend=social(accessActor()).reqOut.find(x=>x.p===id&&x.status==='pending');
 if(pend){sheet(()=>({title:L('Запрос уже отправлен','Request already sent'),lead:`<span class="ico a">${I.clock}</span>`,body:`<p class="lead">${L(`${esc(pname(id))} ещё не ответил(а). Ответ придёт в уведомления.`,`${esc(pname(id))} hasn’t answered yet. You’ll be notified.`)}</p><div class="card list">${linkRow({icon:'lock',title:pend.scopes.map(s=>T(REQ_SCOPES.find(x=>x[0]===s)[1])).join(', '),sub:L('Отправлен','Sent')+' '+F.rel(pend.t),noChev:1})}</div>`,foot:`<button class="btn soft" data-act="cancelReq" data-v="${pend.id}">${L('Отменить запрос','Cancel request')}</button><button class="btn text" data-act="toAccess" data-v="out">${L('Все мои запросы','All my requests')}</button>`}));return;}
 const dec=social(accessActor()).reqOut.find(x=>x.p===id&&x.status==='declined'&&Date.now()-x.t<7*DAY);
 if(dec){toast(L('Повторный запрос этому человеку можно отправить через 7 дней после отказа','You can ask this person again 7 days after a decline'),{type:'warn'});return;}
 if(C.quotaLeft()<=0){limitSheet();return;}
 const scopes=accessActor()==='couple'&&!PEOPLE[id]?.pair?REQ_SCOPES.filter(s=>s[0]==='info'):id==='mia'?REQ_SCOPES:REQ_SCOPES.filter(s=>s[0]!=='album');S.ui.rq={id,actor:accessActor(),ticket:authorTicket(accessActor()),sel:['info']};
 sheet(()=>{const o=S.ui.rq;const left=C.quotaLeft(),max=S.quota.max;return{title:L('Запросить расширенный профиль','Request private profile'),body:`<p class="note" data-couple-request ${accessActor()==='couple'?'':'hidden'}>${L(`Доступ для ${esc(pname('couple'))}.`,`Access for ${esc(pname('couple'))}.`)}</p><p class="lead">${L(`Отметь, что хочешь увидеть. Что открыть — решает ${esc(pname(id))}.`,`Choose what you’d like to see. ${esc(pname(id))} decides what to share.`)}</p>
 ${chipGroup(scopes.map(([k,l])=>[k,T(l)]),o.sel,'rqPick')}
 <div class="sec">${L('Осталось запросов сегодня','Requests left today')}<b style="color:var(--ink)">${left} ${L('из','of')} ${max}</b></div><div class="quota">${Array.from({length:Math.min(max,15)},(_,i)=>`<i class="${i<left?'':'off'}"></i>`).join('')}</div>
 <div class="alert mt16">${I.info}<span>${L('Запрос не отправляет сообщение и не открывает чат. Можно открыть меньше или отказать без объяснения.','A request sends no message and doesn’t open a chat. They can share less or decline without explanation.')}</span></div>`,
 foot:`<button class="btn primary ${o.sel.length?'':'off'}" data-act="rqSend">${L('Отправить запрос','Send request')}</button>`};});};
ACT.rqPick=a=>{const s=S.ui.rq.sel;const i=s.indexOf(a.dataset.v);i<0?s.push(a.dataset.v):s.splice(i,1);resheet();};
ACT.rqSend=a=>{const o=S.ui.rq;if(!o?.sel.length)return;const ticket=o.ticket||authorTicket(o.actor||'me'),reason=requestReason(o.id,ticket.id);if(!validAuthor(ticket))return;if(reason){toast(reason,{type:'warn'});return;}const scopes=[...o.sel].filter(s=>ticket.id!=='couple'||PEOPLE[o.id]?.pair||s==='info');if(!scopes.length)return;let sent=false;
 return run(a,()=>{if(!validAuthor(ticket)||requestReason(o.id,ticket.id)||S.ui.rq!==o)return;social(ticket.id).reqOut.unshift({id:'o'+Date.now(),p:o.id,actor:ticket.id,pairId:ticket.id==='couple'?S.pair.id:null,viewers:realMembers(ticket.id),scopes,t:Date.now(),status:'pending'});autoResolve();S.quota.used++;sent=true;closeSheet();refresh();},{ok:()=>sent?L('Запрос отправлен','Request sent'):null});};
/* B02 — the single paywall moment: quota of new outgoing requests */
function limitSheet(){sheet(()=>({title:L('Запросы на сегодня закончились','No requests left today'),lead:`<span class="ico a">${I.timer}</span>`,body:`<p class="lead">${L(`До ${S.quota.max} новых запросов за 24 часа — это защита от рассылки. Ближайший освободится через 5 ч.`,`Up to ${S.quota.max} new requests per 24 hours — it protects people from spam. The next one frees up in 5 h.`)}</p><p class="note">${L('Отвечать на запросы и отзывать доступ можно всегда.','Answering requests and revoking access are always available.')}</p>`,foot:`<button class="btn primary" data-act="closeSheet">${L('Понятно','Got it')}</button>`}));}
ACT.cancelReq=a=>{const x=social().reqOut.find(y=>y.id===a.dataset.v);run(a,()=>{x.status='cancelled';closeSheet();refresh();},{ok:L('Запрос отменён. Попытка не возвращается','Request cancelled. The attempt isn’t refunded')});};
