ACT.phRm=a=>{if(S.ui.sheet)closeSheet(true);const r=cur();if(requiresDiscoveryPhoto(editableProfile())&&r.photos.length===1){toast(L('Для показа в подборке нужно фото. Сначала выключи показ анкеты в настройках.','A photo is required to appear in Discover. Turn off profile visibility in settings first.'),{type:'warn'});return;}r.photos.splice(+a.dataset.v,1);r.dirty=true;refresh();};
ACT.peSave=a=>{const r=cur(),session=S.session,pair=S.pair;if(r.p.owner==='couple'&&(!coupleWritable(r.pairLease)||(S.pair.draftVersion||0)!==r.pairVersion)){toast(L('Черновик изменился. Открой актуальную версию; введённые данные остаются здесь.','The draft changed. Open the current version; your input stays here.'),{type:'warn'});return;}if(requiresDiscoveryPhoto(r.p.owner==='couple'?{dating:r.datingVisible,datingVisible:r.datingVisible}:editableProfile(r))&&!r.photos.length){toast(L('Для показа в подборке нужно хотя бы одно фото','At least one photo is required to appear in Discover'),{type:'warn'});return;}r.err={};const nk=fv('nick').trim();const ne=r.p.owner==='couple'?(nk.length<2||nk.length>60?L('От 2 до 60 символов','2 to 60 characters'):''):nk.toLowerCase()===S.me.nick.toLowerCase()?'':V.nick(nk);if(ne)r.err.nick=ne;if(fv('bio').length>500)r.err.bio=L('Максимум 500 символов','500 characters max');
 if(Object.keys(r.err).length){refresh();shakeFirstErr();toast(L('Проверь отмеченные поля','Check the highlighted fields'),{type:'err'});return;}
 const bio=fv('bio');if(r.p.owner==='couple'&&r.datingVisible&&(!r.photos.length||S.me.ageCheck!=='ok'||!PEOPLE[pair.with]?.verified)){toast(L('Для знакомств нужны фото и подтверждение 18+ обоих участников','Discover requires a photo and 18+ confirmation for both partners'),{type:'warn'});return;}run(a,()=>{if(S.session!==session||cur()!==r||r.p.owner==='couple'&&S.pair!==pair)return;if(r.p.owner==='couple'&&(!coupleWritable(r.pairLease)||(S.pair.draftVersion||0)!==r.pairVersion)){toast(L('Черновик изменён в другом редакторе. Открой его заново; введённые данные сохранены на этом экране.','The draft changed in another editor. Reopen it; this screen keeps your input.'),{type:'warn'});return;}const m=editableProfile(r);if(!m)return;Object.assign(m,{nick:r.p.owner==='couple'?'couple':nk,...(r.p.owner==='couple'?{name:editedText(m.name,nk)}:{}),bio:editedText(m.bio,bio),city:r.f.city||null,photos:[...r.photos],photo:r.photos[0]||null,showAge:r.showAge,pron:r.pron,gender:r.gender,orient:r.orient,format:[...r.format],status:r.status,role:[...r.role],seek:[...r.seek],vis:{...r.vis},privOn:!!r.privOn,requestsFrom:r.reqFrom,...(r.privOn&&$('[name="privText"]')?{privText:editedText(m.privText,fv('privText').trim().slice(0,1000))}:{}),...(r.p.owner==='couple'?{dating:r.datingVisible,datingVisible:r.datingVisible,socialLikes:false,requestsFrom:r.reqFrom}:{})});if(r.p.owner==='couple')markCoupleDraft(true);r.dirty=false;back();},{ok:r.p.owner==='couple'?L('Черновик сохранён. Отправь общую версию на согласование в профиле пары.','Draft saved. Submit the complete version from the couple profile.'):L('Профиль обновлён','Profile updated')});};

